  "claims": [
    {
      "claim": "L5 Caco-2 bidirectional transport for the coumarins decursin and decursinol shows high apparent permeability (11.1 and 18.3 ×10^-6 cm/s) with efflux ratios of 1.0-1.1, indicating passive diffusion without a significant gut-wall efflux barrier.",
      "card_ids": ["C175","C159"]
    },
    {
      "claim": "Calycosin, a methoxy/phenolic isoflavone, has a Caco-2 Papp of about 3.5 ×10^-5 cm/s and an efflux ratio below 1.5, and crosses membranes by passive diffusion, supporting favorable intestinal absorption for small methoxy/phenolic aromatics.",
      "card_ids": ["C192","C184"]
    },
    {
      "claim": "Genkwanin, a 7-methoxy flavone, shows high rat intestinal effective permeability (P_eff 1.97 ×10^-4 cm/s) in single-pass intestinal perfusion, indicating efficient absorptive transport for a methoxy/phenolic aromatic compound.",
      "card_ids": ["C149"]
    },
    {
      "claim": "Methylated flavones 7,4'-DMF, 5,7-DMF, and 7-MF show high Caco-2 Papp values (25.0, 23.3, and 22.6 ×10^-6 cm/s), and methylated flavones are considerably more permeable than their unmethylated analogues, supporting the favorable absorption of the query's methoxy-substituted coumarin scaffold.",
      "card_ids": ["C196","C155","C180","C172"]
    },
    {
      "claim": "Formononetin, a methoxy isoflavone, has a Caco-2 A→B Papp of 16.1 ×10^-6 cm/s and an efflux ratio of 1.0-1.5, indicating no significant active efflux.",
      "card_ids": ["C161","C153"]
    },
    {
      "claim": "Baicalein and wogonin are easily absorbed across Caco-2 monolayers with high permeability and low glucuronide formation in the gut-wall model, providing no evidence of an intrinsic efflux or intestinal-metabolism barrier for small phenolic aglycones.",
      "card_ids": ["C178","C170","C152","C156","C164","C191"]
    },
    {
      "claim": "L3 oral Cmax records for small phenolics (paeonol 8.61 µg/mL at 70 mg/kg in rats; BHA about 2 µg/mL in mice) and L4 Caco-2 classifications of decursin and decursinol angelate as well absorbed, plus good oral absorption of paeonol and veratric acid, support measurable oral absorption for the query's small phenolic/coumarin scaffold.",
      "card_ids": ["C56","C75","C100","C128","C143","C130"]
    },
    {
      "claim": "The low-F records for chrysin and acacetin concern larger polyphenolic flavones with very low solubility and extensive conjugation; they are not transferable to the small, moderately lipophilic coumarin scopoletin and do not provide affirmative threshold-relevant evidence for F < 20%.",
      "card_ids": ["C02","C32"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C175","C159","C192","C184","C149","C196","C155","C180","C172","C161","C153","C178","C170","C152","C156","C164","C191"]
    }
  ],
  "evidence_gaps": [
    "No direct scopoletin-specific oral bioavailability, AUC/Cmax, or matched oral/IV exposure measurement is present in the supplied records.",
    "No scopoletin-specific gut-wall efflux or intestinal-metabolism assay is present; transfer from decursin/decursinol, calycosin, genkwanin, and methylated flavones is indirect.",
    "First-pass conjugation of the 7-hydroxy group and any lactone-related metabolism are not quantified for scopoletin.",
    "Dose, formulation, species, and sampling differences between the query and the cited records are unknown.",
    "No direct scopoletin solubility or dissolution measurement is supplied; the favorable solubility prior is physicochemical only."
  ],
  "decision_summary": "Predicted high because scopoletin is a small, moderately lipophilic 7-hydroxy-6-methoxycoumarin with favorable physicochemical properties for F >= 20%; L5 adds consistent Caco-2 and intestinal-permeability evidence for structurally related coumarins and methoxy/phenolic aromatics showing high passive permeability and no significant efflux, while no affirmative threshold-relevant low-F evidence for scopoletin was added."
}

